(() => {
  const data = window.RR_REVIRY || [];
  const collator = new Intl.Collator('sk');

  // "Váh č. 7" -> "vah c 7"; matches the keys generated by tools/build_reviry.py
  const norm = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ').trim();
  const tokens = (q) => norm(q).split(' ').filter(Boolean);
  // every typed word must start one of the words in the name or number ("vah 7" finds Váh č. 7, not Váh č. 2)
  const matches = (key, toks) => {
    const words = key.split(' ');
    return toks.every((t) => words.some((w) => w.startsWith(t)));
  };
  const plural = (n) => (n === 1 ? 'revír' : (n >= 2 && n <= 4 ? 'revíry' : 'revírov'));
  // Slovak participle agrees with the count: nájdený 1 revír, nájdené 3 revíry, nájdených 7 revírov
  const counted = (stem, n) => `${stem}${n === 1 ? 'ý' : (n >= 2 && n <= 4 ? 'é' : 'ých')} ${n} ${plural(n)}`;
  const typeWord = { k: 'kaprový', l: 'lipňový' };
  const escapeHtml = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const keepTogether = (s) => escapeHtml(s).replace(/č\. /g, 'č.&nbsp;');

  const search = (q) => {
    const toks = tokens(q);
    if (!toks.length) return [];
    const whole = toks.join(' ');
    return data
      .filter((r) => matches(r.k, toks))
      .sort((a, b) => (Number(b.k.startsWith(whole)) - Number(a.k.startsWith(whole))) || collator.compare(a.n, b.n));
  };

  // Arrow keys move between the search field and the result links
  const arrowNav = (input, list) => {
    const links = () => Array.from(list.querySelectorAll('a'));
    input.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown' && links().length) { e.preventDefault(); links()[0].focus(); }
      if (e.key === 'Escape') { input.value = ''; input.dispatchEvent(new Event('input')); }
    });
    list.addEventListener('keydown', (e) => {
      const all = links();
      const i = all.indexOf(document.activeElement);
      if (i < 0) return;
      if (e.key === 'ArrowDown' && all[i + 1]) { e.preventDefault(); all[i + 1].focus(); }
      if (e.key === 'ArrowUp') { e.preventDefault(); (all[i - 1] || input).focus(); }
    });
  };

  // Homepage: live results under the search field
  const live = document.querySelector('[data-revir-live]');
  if (live) {
    const input = live.querySelector('input[type="search"]');
    const list = live.querySelector('[data-results]');
    const status = live.querySelector('[data-status]');
    const popular = live.querySelector('[data-popular]');
    const base = live.dataset.base || '';
    const MAX = 6;

    const render = () => {
      const q = input.value.trim();
      const found = search(q);
      if (!q) {
        list.hidden = true;
        list.innerHTML = '';
        status.textContent = '';
        if (popular) popular.hidden = false;
        return;
      }
      if (popular) popular.hidden = true;
      list.hidden = false;
      if (!found.length) {
        status.textContent = 'Taký revír sme nenašli. Skúste iný názov alebo číslo revíru.';
        list.innerHTML = '';
        return;
      }
      status.textContent = found.length > MAX
        ? `${counted('Nájden', found.length)}, zobrazujeme prvých ${MAX}.`
        : `${counted('Nájden', found.length)}.`;
      const items = found.slice(0, MAX).map((r) => `<li><a class="revir-row" href="${base}revir/${r.s}.html">`
        + `<span class="revir-row__name">${keepTogether(r.n)}</span>`
        + `<span class="revir-row__num">${escapeHtml(r.c)}</span>`
        + `<span class="revir-row__type"><span class="type-dot type-dot--${r.t}" aria-hidden="true"></span>${typeWord[r.t]}</span>`
        + '</a></li>');
      if (found.length > MAX) {
        items.push(`<li><a class="revir-row revir-row--more" href="${base}reviry.html?q=${encodeURIComponent(q)}">`
          + `Zobraziť všetkých ${found.length} výsledkov</a></li>`);
      }
      list.innerHTML = items.join('');
    };
    input.addEventListener('input', render);
    arrowNav(input, list);
    render();
  }

  // List page: filter the full list in place
  const form = document.querySelector('[data-revir-filter]');
  if (form) {
    const input = form.querySelector('input[type="search"]');
    const radios = Array.from(form.querySelectorAll('input[name="t"]'));
    const groups = Array.from(document.querySelectorAll('.letter-group'));
    const count = document.querySelector('[data-count]');
    const empty = document.querySelector('[data-empty]');

    const params = new URLSearchParams(window.location.search);
    if (params.get('q')) input.value = params.get('q');
    const t0 = params.get('t');
    radios.forEach((r) => { r.checked = r.value === (t0 === 'k' || t0 === 'l' ? t0 : ''); });

    const apply = () => {
      const toks = tokens(input.value);
      const type = (radios.find((r) => r.checked) || {}).value || '';
      let shown = 0;
      groups.forEach((g) => {
        let inGroup = 0;
        g.querySelectorAll('li').forEach((li) => {
          const ok = (!type || li.dataset.type === type) && (!toks.length || matches(li.dataset.search, toks));
          li.hidden = !ok;
          if (ok) inGroup += 1;
        });
        g.hidden = inGroup === 0;
        shown += inGroup;
      });
      count.textContent = shown ? counted('Zobrazen', shown) : 'Žiadny revír nezodpovedá hľadaniu';
      empty.hidden = shown > 0;
      try {
        const p = new URLSearchParams();
        if (input.value.trim()) p.set('q', input.value.trim());
        if (type) p.set('t', type);
        const qs = p.toString();
        window.history.replaceState(null, '', qs ? `?${qs}` : window.location.pathname);
      } catch (e) { /* URL update is optional */ }
    };

    form.addEventListener('submit', (e) => { e.preventDefault(); apply(); });
    input.addEventListener('input', apply);
    radios.forEach((r) => r.addEventListener('change', apply));
    apply();
  }
})();
